const asset='../../../public/assets/';
const brand=`<img class="brand" src="${asset}branding/heypals-logo.png" alt="HeyPals">`;
const header=(time='0:33',meta='Round 1 / 7')=>`<header class="phone-head"><div class="identity"><i>2</i><span>players</span></div>${brand}<div class="clock"><strong>${time}</strong><small>${meta}</small></div></header>`;
const footer=`<footer class="phone-foot"><button type="button"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5v14M16 5v14"/></svg><span>Pause</span></button><button type="button"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m10 5-7 7 7 7M3 12h18"/></svg><span>Lobby</span></button></footer>`;
const knives=`${header()}<main class="phone-content"><p class="eyebrow">Knives</p><h2 class="game-title">Hit your color</h2><p class="hint">Watch the screen. Time your throw.</p><div class="action-zone"><div class="inventory"><i class="blade"></i><i class="blade"></i><i class="blade"></i><i class="blade"></i><i class="blade used"></i><span>4 of 5</span></div><button class="big-action" type="button"><svg viewBox="0 0 48 48" aria-hidden="true"><path d="M28 7 19 27l6 3L38 10 28 7ZM19 27l-7 12 5 3 8-12M17 25l11 7"/></svg><strong>THROW</strong><span>Tap at the right moment</span></button></div><div class="stats"><div><span>Round</span><strong>12</strong></div><div><span>Total</span><strong>48</strong></div></div></main>${footer}`;
const punch=`${header('1:12','Time left')}<main class="phone-content"><p class="eyebrow">Punch Meter</p><h2 class="game-title">Feel the power</h2><p class="hint">Hold to build power. Release at the peak.</p><div class="punch-meter"><svg viewBox="0 0 244 157" aria-hidden="true"><path d="M20 132 A102 102 0 0 1 224 132" pathLength="100" class="meter-track"/><path d="M20 132 A102 102 0 0 1 224 132" pathLength="100" class="meter-fill"/></svg><div class="meter-value"><strong>74<span style="display:inline;font-size:18px;color:var(--muted)">%</span></strong><span>Punch Meter</span></div></div><button class="motion" type="button">Enable motion controls ↗</button><button class="hold-action" type="button">HOLD → RELEASE</button><div class="stats"><div><span>Attempts</span><strong>1/3</strong></div><div><span>Best</span><strong>74</strong></div><div><span>Total</span><strong>74</strong></div></div></main>${footer}`;
const names=['Alexandria Longlastname','Christopher Featherstone','Ўладзімір','Ілля · Ёжик','Natalie','Michael','Victoria','Sofia','Artem','Eugene','Alice','Max','Olivia','Dennis','Jaroslav','Anna'];
const results=`${header('Results','16 players')}<main class="phone-content"><div class="result-header"><p class="eyebrow">TAP RACE · MATCH COMPLETE</p><h2 class="game-title">You crushed it.</h2><p class="hint">First place. Keep that energy.</p></div><div class="result-columns"><span>№</span><span>Player</span><span>Score</span></div><ol class="result-list">${names.map((n,i)=>`<li><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="name">${n}${i===0?'<small>You</small>':''}</span><strong class="value">${Math.max(0,64-i*5)}</strong></li>`).join('')}</ol></main>${footer}`;
document.querySelector('#phone-grid').innerHTML=[['knives','01 / ONE ACTION',knives],['punch','02 / HOLD AND RELEASE',punch],['results','03 / RESULTS · 16 PLAYERS',results]].map(([id,title,body])=>`<article class="specimen" data-view="${id}"><h2>${title}</h2><div class="phone ${id}">${body}</div></article>`).join('');
document.querySelector('#tv-section').innerHTML=`<h2>04 / TV · LABELS BELONG TO THE FIELD</h2><div class="tv"><header class="tv-header"><div class="tv-game">${brand}<div class="tv-game-name">Air Hockey<small>Defend your goal. Score goals.</small></div></div><div class="tv-score"><b>3</b><i>:</i><b>2</b></div><div class="tv-time"><strong>0:59</strong><small>Time left</small></div></header><div class="field-wrap"><div class="field"><img src="${asset}gameplay/tabletop/hockey-field.webp" alt="Air hockey field"><div class="striker" style="left:15%;top:24%"><span class="striker-label">Alexandria</span></div><div class="striker" style="left:24%;top:66%"><span class="striker-label">Bot 3</span></div><div class="striker purple" style="left:70%;top:31%"><span class="striker-label">Bot 1</span></div><div class="striker purple" style="left:82%;top:61%"><span class="striker-label">Bot 2</span></div><div class="puck"></div></div><div class="touch-rail"><div class="touch"><div><small>Last touch</small><strong>Alexandria Longlastname</strong></div></div><div class="touch"><div><small>Last touch</small><strong>Bot 2</strong></div></div></div></div></div>`;
document.querySelector('#type-section').innerHTML=`<h2>THREE DIRECTIONS · IDENTICAL CONTENT</h2><div class="type-grid">${[['a','A / ANYBODY ITALIC + ONEST','Recommended: kinetic, broad italic for action and headline. Stable upright numerals. Calm names and instructions.'],['b','B / OXANIUM + ONEST','Angular, technical console. Squared terminals and compact numerals. All upright, without forced slant.'],['c','C / UNBOUNDED + ONEST','Wide, playful geometry. Distinctive upright letterforms, softer rhythm and generous counters.']].map(([d,label,copy])=>`<article class="type-card direction-${d}"><span class="label">${label}</span><h3>Hit your color</h3><p>Watch the screen. Time your throw.<br>Tap at the right moment.</p><div class="digits">0:59 / 1000</div><div class="glyphs">Пётр · Ёжик · Ілля<br>Ўладзімір · Йй · Щщ</div><p>${copy}</p></article>`).join('')}</div>`;
function direction(d){document.body.dataset.direction=d;document.querySelectorAll('[data-font]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.font===d)));}
function screen(view,solo=false){document.querySelector('#western-review').classList.toggle('hidden',view!=='western');document.querySelector('#jenga-review').classList.toggle('hidden',view!=='jenga');document.body.classList.toggle('solo',solo);document.querySelector('.intro').classList.toggle('hidden',view!=='board');document.querySelector('#phone-grid').classList.toggle('hidden',['hockey','type','jenga','western'].includes(view));document.querySelectorAll('.specimen').forEach(e=>e.classList.toggle('hidden',view!=='board'&&e.dataset.view!==view));document.querySelector('#tv-section').classList.toggle('hidden',!['board','hockey'].includes(view));document.querySelector('#type-section').classList.toggle('hidden',!['board','type'].includes(view));}
document.querySelectorAll('[data-font]').forEach(b=>b.onclick=()=>direction(b.dataset.font));document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>screen(b.dataset.screen));
const query=new URLSearchParams(location.search);direction(query.get('font')||'combined');screen(query.get('screen')||'board',query.has('solo'));

function stageTreatment(value,focus=false){document.body.dataset.stage=value;document.querySelectorAll('[data-stage]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.stage===value)));if(focus){direction('combined');screen('hockey');document.querySelector('#tv-section').scrollIntoView({block:'start'});}}
document.querySelectorAll('button[data-stage]').forEach(b=>b.onclick=()=>stageTreatment(b.dataset.stage,true));stageTreatment(query.get('stage')||'clean');
